import{_ as e,a,b as r,c as l,d as o}from"./chunks/right.CNmiwBYW.js";import{_ as i,o as s,c as d,al as n}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"S-Vehicle E2","description":"","frontmatter":{},"headers":[],"relativePath":"ko/flight_controller/svehicle_e2.md","filePath":"ko/flight_controller/svehicle_e2.md"}'),u={name:"ko/flight_controller/svehicle_e2.md"};function h(c,t,p,m,b,P){return s(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="s-vehicle-e2" tabindex="-1">S-Vehicle E2 <a class="header-anchor" href="#s-vehicle-e2" aria-label="Permalink to &quot;S-Vehicle E2&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 does not manufacture this (or any) autopilot.</p></div><p>The <em>E2</em> is an advanced autopilot manufactured by S-Vehicle<sup>®</sup>.</p><p>The autopilot is recommended for commercial system integration, but is also suitable for academic research and any other applications. It brings you ultimate performance, stability, and reliability in every aspect.</p><p><img src="'+e+'" alt="SVehicle-E2"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>이 비행 컨트롤러는 <a href="./../flight_controller/autopilot_manufacturer_supported">제조업체에서 지원</a>합니다.</p></div><h3 id="processors-sensors" tabindex="-1">Processors &amp; Sensors <a class="header-anchor" href="#processors-sensors" aria-label="Permalink to &quot;Processors &amp; Sensors&quot;">​</a></h3><ul><li>FMU Processor: STM32H753IIK6 <ul><li>32 Bit Arm® Cortex®-M7, 480MHz, 2MB flash memory, 1MB RAM</li></ul></li><li>IO Processor: STM32F103 <ul><li>32 Bit Arm® Cortex®-M3, 72MHz, 20KB SRAM</li></ul></li><li>내장 센서 : <ul><li>Accel/Gyro: BMI088</li><li>Accel/Gyro: ICM-42688-P</li><li>Accel/Gyro: ICM-20649</li><li>Mag: RM3100</li><li>Barometer: 2x ICP-20100</li></ul></li></ul><h3 id="인터페이스" tabindex="-1">인터페이스 <a class="header-anchor" href="#인터페이스" aria-label="Permalink to &quot;인터페이스&quot;">​</a></h3><ul><li>14x PWM Servo Outputs</li><li>1x Dedicated R/C Input for Spektrum / DSM and S.Bus</li><li>1x Analog/PWM RSSI Input</li><li>2x TELEM Ports (with full flow control)</li><li>1x UART4 Port</li><li>2x GPS Ports <ul><li>1x Full GPS plus Safety Switch Port (GPS1)</li><li>1x Basic GPS Port (with I2C, GPS2)</li></ul></li><li>1x USB Port (TYPE-C)</li><li>1x Ethernet Port <ul><li>Transformerless application</li><li>100Mbps</li></ul></li><li>3x I2C Bus Ports</li><li>1x SPI Bus <ul><li>1x Chip Select Line</li><li>1x Data Ready Line</li><li>1x SPI Reset Line</li></ul></li><li>2x CAN Ports</li><li>3x Power Input Ports <ul><li>ADC Power Input</li><li>I2C Power Input</li><li>DroneCAN/UAVCAN Power Input</li></ul></li><li>2x AD Ports <ul><li>Analog Input (3.3V)</li><li>Analog Input (6.6V - not supported by PX4)</li></ul></li><li>1x Dedicated Debug Port <ul><li>FMU Debug</li></ul></li></ul><h2 id="store" tabindex="-1">Purchase Channels <a class="header-anchor" href="#store" aria-label="Permalink to &quot;Purchase Channels {#store}&quot;">​</a></h2><p>Order from <a href="https://svehicle.cn/" target="_blank" rel="noreferrer">S-Vehicle</a>.</p><h2 id="무선-조종" tabindex="-1">무선 조종 <a class="header-anchor" href="#무선-조종" aria-label="Permalink to &quot;무선 조종&quot;">​</a></h2><p>A Radio Control (RC) system is required if you want to manually control your vehicle (PX4 does not require a radio system for autonomous flight modes).</p><p>기체와 조종자가 통신하기 위하여 송신기와 수신기를 바인딩하여야 합니다. 송신기와 수신기의 매뉴얼을 참고하십시오.</p><p>Spektrum/DSM receivers connect to the DSM/SBUS RC input. PPM or SBUS receivers connect to the RC IN input port. CRSF receiver must be wired to a spare port (UART) on the Flight Controller. Then you can bind the transmitter and receiver together.</p><h2 id="시리얼-포트-매핑" tabindex="-1">시리얼 포트 매핑 <a class="header-anchor" href="#시리얼-포트-매핑" aria-label="Permalink to &quot;시리얼 포트 매핑&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UART</th><th>장치</th><th>포트</th></tr></thead><tbody><tr><td>USART1</td><td>/dev/ttyS0</td><td>GPS</td></tr><tr><td>USART2</td><td>/dev/ttyS1</td><td>TELEM3</td></tr><tr><td>USART3</td><td>/dev/ttyS2</td><td>디버그 콘솔</td></tr><tr><td>UART4</td><td>/dev/ttyS3</td><td>UART4</td></tr><tr><td>UART5</td><td>/dev/ttyS4</td><td>TELEM2</td></tr><tr><td>USART6</td><td>/dev/ttyS5</td><td>PX4IO/RC</td></tr><tr><td>UART7</td><td>/dev/ttyS6</td><td>TELEM1</td></tr><tr><td>UART8</td><td>/dev/ttyS7</td><td>GPS2</td></tr></tbody></table><h2 id="pwm-output" tabindex="-1">PWM Output <a class="header-anchor" href="#pwm-output" aria-label="Permalink to &quot;PWM Output&quot;">​</a></h2><p>The E2-Plus flight controller supports up to 14 PWM outputs. The first 8 outputs (labelled M1 to M8) are controlled by a dedicated STM32F103 IOMCU controller. The remaining 6 outputs (labelled 9 to 14) are the &quot;auxiliary&quot; outputs. These are directly attached to the STM32H753 FMU controller .</p><p>The 14 PWM outputs are:</p><p>M1 - M8 are connected to the IOMCU A1 - A6 are connected to the FMU</p><p>M1 - M8 support DShot and are in 3 groups:</p><ul><li>M1, M2 in group 1</li><li>M3, M4 in group 2</li><li>M5, M6, M7, M8 in group 3</li></ul><p>The 6 FMU PWM outputs are in 2 groups:</p><p>A1 - A4 are in one group. A5, A6 are in a 2nd group.</p><p>Channels within the same group need to use the same output rate. If any channel in a group uses DShot then all channels in the group need to use DShot.</p><h3 id="electrical-data" tabindex="-1">Electrical data <a class="header-anchor" href="#electrical-data" aria-label="Permalink to &quot;Electrical data&quot;">​</a></h3><ul><li>Voltage Ratings: <ul><li>Max input voltage: 5.7V</li><li>USB Power Input: 4.75~5.25V</li><li>Servo Rail Input: 0~9.9V</li></ul></li><li>Current Ratings: <ul><li>TELEM1 and GPS2 combined output current limiter: 1.5A</li><li>All other port combined output current limiter: 1.5A</li></ul></li></ul><h2 id="battery-monitoring" tabindex="-1">Battery Monitoring <a class="header-anchor" href="#battery-monitoring" aria-label="Permalink to &quot;Battery Monitoring&quot;">​</a></h2><p>The board has connectors for 3 power monitors.</p><ul><li>POWER1 -- ADC</li><li>POWER2 -- DroneCAN</li><li>POWER3 -- I2C</li></ul><p>The board is configure by default for a analog power monitor, and also has DroneCAN power monitor and I2C defaults configured which is enabled.</p><p>The default PDB included with the E2+ is analog and must be connected to <code>POWER1</code>.</p><h2 id="펌웨어-빌드" tabindex="-1">펌웨어 빌드 <a class="header-anchor" href="#펌웨어-빌드" aria-label="Permalink to &quot;펌웨어 빌드&quot;">​</a></h2><p>To <a href="./../dev_setup/building_px4">build PX4</a> for this target, execute:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> svehicle_e2_default</span></span></code></pre></div><h2 id="디버그-포트" tabindex="-1">디버그 포트 <a class="header-anchor" href="#디버그-포트" aria-label="Permalink to &quot;디버그 포트&quot;">​</a></h2><p>The <a href="./../debug/system_console">PX4 System Console</a> and <a href="./../debug/swd_debug">SWD Interface</a> operate on the <strong>FMU Debug</strong> port.</p><table tabindex="0"><thead><tr><th>핀</th><th>신호</th><th>전압</th></tr></thead><tbody><tr><td>1(red)</td><td>5V+</td><td>+5V</td></tr><tr><td>2 (흑)</td><td>DEBUG TX(출력)</td><td>+3.3V</td></tr><tr><td>3 (흑)</td><td>DEBUG TX(입력)</td><td>+3.3V</td></tr><tr><td>4 (흑)</td><td>FMU_SWDIO</td><td>+3.3V</td></tr><tr><td>5 (흑)</td><td>FMU_SWCLK</td><td>+3.3V</td></tr><tr><td>6 (흑)</td><td>GND</td><td>GND</td></tr></tbody></table><p>For information about using this port see:</p><ul><li><a href="./../debug/swd_debug">SWD Debug Port</a></li><li><a href="./../debug/system_console">PX4 System Console</a> (Note, the FMU console maps to USART3).</li><li>All ports use GH1.25 ,power ports use ports on E2 uses the 6 circuit <a href="https://www.molex.com/en-us/products/part-detail/5024430670" target="_blank" rel="noreferrer">2.00mm Pitch CLIK-Mate Wire-to-Board PCB Receptacle</a>.</li></ul><h2 id="핀배열" tabindex="-1">핀배열 <a class="header-anchor" href="#핀배열" aria-label="Permalink to &quot;핀배열&quot;">​</a></h2><p><img src="'+a+'" alt="SVehicle-E2 Top Down Photo"></p><p><img src="'+r+'" alt="SVehicle-E2 Bottom Photo"></p><p><img src="'+l+'" alt="SVehicle-E2 left Photo"></p><p><img src="'+o+'" alt="SVehicle-E2 right Photo"></p><h2 id="지원-플랫폼-및-기체" tabindex="-1">지원 플랫폼 및 기체 <a class="header-anchor" href="#지원-플랫폼-및-기체" aria-label="Permalink to &quot;지원 플랫폼 및 기체&quot;">​</a></h2><p>Any multirotor/airplane/rover or boat that can be controlled using normal RC servos or Futaba S-Bus servos. The complete set of supported configurations can be found in the <a href="./../airframes/airframe_reference">Airframe Reference</a>.</p>',49)])])}const M=i(u,[["render",h]]);export{g as __pageData,M as default};
